    if(d==="set:diag") return this.cmdDiagToken(chat,mid,uid);
    if(d==="set:ib") return this.cmdIbPush(chat,mid,uid);
    if(d==="set:ib_new") return this.onIbSecretNew(chat,mid,uid);
