  /**
   * 🗣 f57: کارتِ «متن خوش‌آمد» — هر زبان متنِ خودش را دارد و پیش‌نمایشِ
   *   **همان چیزی** است که کاربرِ آن زبان می‌بیند.
   */
  async pubWelcome(chat, mid) {
    const lang = await this.lang();
    const cfg = await this.store.getPublicCfg();
    const state = (v, def) => (String(v || "").trim() && String(v) !== String(def)) ? L(lang, "سفارشی", "custom") : L(lang, "پیش‌فرض", "default");
    const prev = (txt) => {
      const one = String(txt || "").replace(/\\n/g, " ").replace(/\n/g, " ").trim();
      return one ? ("_" + esc(one.slice(0, 90)) + (one.length > 90 ? "…" : "") + "_") : L(lang, "_خالی_", "_empty_");
    };
    const lines = [
      uiHead("👋", L(lang, "متن خوش‌آمد کاربر", "User welcome text"),
        L(lang, "هر زبان، متنِ خودش — کاربرِ انگلیسی هیچ‌وقت فارسی نمی‌بیند", "Each language has its own text")),
      "",
      "🇮🇷 *" + L(lang, "فارسی", "Persian") + "* · *" + state(cfg.welcomeText, DEFAULT_PUBLIC_CFG.welcomeText) + "*",
      prev(this._welcomeFor(cfg, "fa")),
      "",
      "🇬🇧 *English* · *" + state(cfg.welcomeTextEn, DEFAULT_PUBLIC_CFG.welcomeTextEn) + "*",
      prev(this._welcomeFor(cfg, "en")),
      "",
      L(lang, "_جانگهدار: `\\n` برای خطِ تازه · `-` برای بازگشت به پیش‌فرض_",
             "_Placeholder: `\\n` new line · `-` restores the default_"),
    ];
    await this.editOrSend(chat, mid, lines.join("\n"), kb([
      [btn(L(lang, "✏️ ویرایش فارسی", "✏️ Edit Persian"), "pub:wel_fa")],
      [btn("✏️ Edit English", "pub:wel_en")],
      [btn(L(lang, "♻️ بازگردانی هر دو به پیش‌فرض", "♻️ Reset both to defaults"), "pub:wel_rst")],
      navPair(lang, "pub:custom"),
    ]));
  }
  /** بازگردانیِ هر دو متنِ خوش‌آمد به پیش‌فرض (f57). */
