  /** ساخت و آپلودِ بکاپ. خروجی: {ok, file, count, bytes, gz} */
  async ghBackupNow(reason) {
    const gh=await this.store.getGhBackup();
    if(!gh || !gh.token || !gh.repo) return { ok:false, err:"not configured" };
    const snap=await this.store.exportAllRows();
    if(!snap) return { ok:false, err:"no D1 binding" };
    const body=JSON.stringify({ v:1, stamp:CODE_STAMP, ts:new Date().toISOString(), count:snap.count, keys:snap.keys });
    const gz=await gzipText(body);
    const data = gz ? bytesToB64(gz) : bytesToB64(new TextEncoder().encode(body));
    const iso=new Date().toISOString();
    const day=iso.slice(0,10), hm=iso.slice(11,16).replace(":","");
    const file="backups/xpanel-"+day+"-"+hm+"-"+(reason==="pre-restore"?"pre-restore":(reason||"auto"))+".json"+(gz?".gz":"");
    // sha فعلی (اگر فایل هست) — برای به‌روزرسانی لازم است
    let sha=null;
    try{ const g=await ghApi(gh, "/contents/"+file, "GET", null, "application/vnd.github+json"); if(g.ok){ const j=await g.json(); sha=j.sha; } }catch{}
    const put=await ghApi(gh, "/contents/"+file, "PUT", {
      message: "backup "+day+" ("+snap.count+" keys, "+Math.round(body.length/1024)+"KB"+(gz?" gz":"")+")",
      content: data, branch: gh.branch||"main", ...(sha?{sha}:{})
    });
    if(!put.ok){
      const t2=await put.text().catch(()=> "");
      return { ok:false, err:"upload "+put.status+" "+String(t2).slice(0,120) };
    }
    gh.lastAt=Date.now();
    try{ await this.store.saveGhBackup(gh); }catch{}
    // f54: نگهداشت — پوشهٔ backups/ تمیز بماند (آخرین ۳۰ نسخه)
    let pruned=0;
    try{ pruned = await this.ghPruneBackups(gh, 30); }catch{}
    if(pruned) console.log("gh prune: removed "+pruned+" old backup(s)");
    return { ok:true, file, count:snap.count, bytes:body.length, gz:!!gz, pruned };
  }
  async onGhBackupNow(chat,mid,uid) {
    const lang=await this.lang();
    await this.editOrSend(chat,mid,L(lang,"⏳ در حال ساختِ بکاپ…","⏳ Building backup…"),kb([[btn(t(lang,"back"),"m:tools")]]));
    const r=await this.ghBackupNow("manual");
    if(!r.ok){
      return this.editOrSend(chat,mid,L(lang,"❌ بکاپ نشد: ","❌ Backup failed: ")+esc(r.err),kb([[btn(L(lang,"🔄 تلاش دوباره","🔄 Retry"),"gh:now")],[btn(t(lang,"back"),"m:tools")]]));
    }
    await this.addLog("gh_backup", r.file+" keys="+r.count, uid);
    return this.editOrSend(chat,mid,
      L(lang,"✅ *بکاپ ساخته شد*\n\n🗂 ","✅ *Backup created*\n\n🗂 ")+"`"+esc(r.file)+"`\n"
      +L(lang,"🔑 کلیدها: ","🔑 Keys: ")+"*"+r.count+"*\n"
      +L(lang,"📦 حجمِ خام: ","📦 Raw size: ")+Math.round(r.bytes/1024)+"KB"+(r.gz?L(lang," (فشرده ✅)"," (gzip ✅)"):"")+(r.pruned?L(lang,"🌿 نسخه‌های قدیمیِ پاک‌شده: ","🌿 Old backups pruned: ")+r.pruned:""),
      kb([[btn(L(lang,"♻️ بازیابی از بکاپ","♻️ Restore"),"gh:restore")],[btn("☁️","gh:menu"), btn(t(lang,"back"),"m:tools")]]));
  }
  /** فهرستِ آخرین بکاپ‌ها روی مخزن. */
  /**
   * f54: نگهداشتِ پوشهٔ `backups/` — آخرین `keep` نسخه می‌مانند و قدیمی‌ترها
   * حذف می‌شوند (حداکثر ۳ حذف در هر اجرا تا فشار روی سقفِ گیت‌هاب نیاید).
   * خروجی: تعدادِ فایل‌های حذف‌شده.
   */
  async ghPruneBackups(gh, keep) {
    const K = Math.max(5, Number(keep)||30);
    let l=null;
    try{ l = await this.ghListBackups(gh, 1000); }catch{ return 0; }
    if(!l || !l.ok || !l.items || l.items.length<=K) return 0;
    let n=0;
    for(const it of l.items.slice(K, K+3)){
      try{
        const g = await ghApi(gh, "/contents/backups/"+encodeURIComponent(it.name)+"?ref="+encodeURIComponent(gh.branch||"main"), "GET", null, "application/vnd.github+json");
        if(!g.ok) continue;
        const j = await g.json();
        const d = await ghApi(gh, "/contents/backups/"+encodeURIComponent(it.name), "DELETE",
                              { message: "prune old backup "+it.name, sha: j.sha, branch: gh.branch||"main" });
        if(d.ok) n++;
      }catch{}
    }
    return n;
  }
  async ghListBackups(gh, limit) {
    const r=await ghApi(gh, "/contents/backups?ref="+encodeURIComponent(gh.branch||"main"), "GET", null, "application/vnd.github+json");
    if(!r.ok) return { ok:false, err:"list "+r.status, items:[] };
    let arr=[];
    try{ arr=await r.json(); }catch{ arr=[]; }
    if(!Array.isArray(arr)) return { ok:false, err:"bad listing", items:[] };
    const items=arr.filter(x=>x && /xpanel-.*\.json(\.gz)?$/.test(x.name||""))
                   .sort((a,b)=>String(b.name).localeCompare(String(a.name)))
                   .slice(0, Math.max(1, Number(limit)||6));
    return { ok:true, items };
  }
