  async onGhRestoreDo(chat,mid,uid,file) {
    const lang=await this.lang();
    const gh=await this.store.getGhBackup();
    if(!gh||!gh.token||!gh.repo) return this.cmdGhMenu(chat,mid);
    await this.editOrSend(chat,mid,L(lang,"⏳ اول یک بکاپِ ایمنی از وضعیتِ فعلی…","⏳ Taking a safety backup first…"),kb([[btn(t(lang,"back"),"m:tools")]]));
    const safe=await this.ghBackupNow("pre-restore").catch(e=>({ok:false,err:String((e&&e.message)||e)}));
    await this.editOrSend(chat,mid,L(lang,"⏳ در حال خواندنِ بکاپ و بازگردانی…","⏳ Downloading and restoring…"),kb([[btn(t(lang,"back"),"m:tools")]]));
    let txt="", raw="";
    const r=await ghApi(gh, "/contents/"+file+"?ref="+encodeURIComponent(gh.branch||"main"), "GET", null, "application/vnd.github.raw");
    if(!r.ok) return this.editOrSend(chat,mid,L(lang,"❌ خواندنِ فایل نشد: ","❌ Could not read file: ")+r.status,kb([[btn(t(lang,"back"),"gh:menu")]]));
    if(/\.gz$/.test(file)){
      const buf=new Uint8Array(await r.arrayBuffer());
      txt=await gunzipText(buf);
    } else { txt=await r.text(); }
    if(!txt) return this.editOrSend(chat,mid,L(lang,"❌ فایلِ بکاپ خوانده/باز نشد.","❌ Backup file could not be read/decompressed."),kb([[btn(t(lang,"back"),"gh:menu")]]));
    let obj=null;
    try{ obj=JSON.parse(txt); }catch(e){ return this.editOrSend(chat,mid,L(lang,"❌ محتوای بکاپ معتبر نیست.","❌ Invalid backup content."),kb([[btn(t(lang,"back"),"gh:menu")]])); }
    if(!obj || !obj.keys || typeof obj.keys!=="object") return this.editOrSend(chat,mid,L(lang,"❌ ساختارِ بکاپ ناشناخته است.","❌ Unknown backup structure."),kb([[btn(t(lang,"back"),"gh:menu")]]));
    let n=0;
    try{ n=await this.store.importRows(obj.keys); }
    catch(e){ return this.editOrSend(chat,mid,L(lang,"❌ بازیابی نیمه‌کاره ماند: ","❌ Restore failed midway: ")+esc(String((e&&e.message)||e).slice(0,140)),kb([[btn(t(lang,"back"),"gh:menu")]])); }
    await this.addLog("gh_restore", file+" keys="+n, uid);
    await this.notifyOwner("♻️ بازیابی انجام شد: `"+String(file).split("/").pop()+"` · "+n+" کلید"+(safe&&safe.ok?" · بکاپِ ایمنی ساخته شد ✅":""));
    return this.editOrSend(chat,mid,
      L(lang,"✅ *بازیابی انجام شد*\n\n🔑 ","✅ *Restore done*\n\n🔑 ")+"*"+n+"*"+L(lang," کلید نوشته شد.\n🗂 از: "," keys written.\n🗂 From: ")+"`"+esc(String(file).split("/").pop())+"`\n\n"
      +(safe&&safe.ok?L(lang,"🛟 بکاپِ ایمنیِ وضعیتِ قبلی هم گرفته شد.","🛟 A safety backup of the previous state was created."):L(lang,"⚠️ بکاپِ ایمنی گرفته نشد (","⚠️ Safety backup failed (")+esc((safe&&safe.err)||"?")+")"),
      kb([[btn(L(lang,"🔄 بروزرسانیِ منو","🔄 Refresh menu"),"m:main")],[btn("☁️","gh:menu"), btn(t(lang,"back"),"m:tools")]]));
  }

